<script setup lang="ts">
import { onMounted, ref, watch } from 'vue'
import { request, type Session } from '../api'
const props=defineProps<{ id?: string }>(); const rows=ref<Session[]>([]); const detail=ref<any>(null); const query=ref(''); const loading=ref(false); const error=ref('')
async function load(){loading.value=true;error.value='';try{if(props.id){detail.value=await request('/sessions/'+props.id)}else{rows.value=await request<Session[]>('/sessions')}}catch(e){error.value=e instanceof Error?e.message:'会话加载失败'}finally{loading.value=false}}
onMounted(load);watch(()=>props.id,load)
</script>
<template><section class="page-view"><div class="page-heading"><div><span class="eyebrow">DIAGNOSIS SESSIONS</span><h2>{{ props.id ? '会话详情' : '诊断会话' }}</h2><p>{{ props.id?'查看完整消息、阶段状态和引用证据。':'所有诊断任务的可追溯记录。' }}</p></div><RouterLink v-if="props.id" class="button secondary" to="/sessions">返回列表</RouterLink><RouterLink v-else class="button primary" to="/diagnosis">新建诊断</RouterLink></div><p v-if="error" class="inline-error">{{ error }} <button class="link-button" @click="load">重试</button></p><div v-if="loading" class="loading-state">正在加载…</div><template v-else-if="props.id && detail"><div class="detail-card"><div class="detail-title"><div><span class="eyebrow">{{ detail.status }}</span><h3>{{ detail.title }}</h3></div><span class="pill">{{ detail.device_id || '未绑定设备' }}</span></div><div v-for="message in detail.messages" :key="message.id" class="message-row"><span class="message-role">{{ message.role==='user'?'用户':'助手' }}</span><div><strong>{{ message.text || '（无文本）' }}</strong><small>{{ new Date(message.created_at).toLocaleString('zh-CN') }}</small><div v-if="message.citations?.length" class="citation-mini">引用 {{ message.citations.length }} 条 · {{ Object.entries(message.stage_states||{}).filter(([,v])=>typeof v==='string').map(([k,v])=>k+': '+v).join(' / ') }}</div></div></div><div v-if="!detail.messages?.length" class="empty-panel">该会话暂无消息。</div></div></template><template v-else><div class="toolbar"><input v-model="query" placeholder="搜索会话标题或设备编号" aria-label="搜索会话"></div><div class="table-wrap"><table><thead><tr><th>会话</th><th>设备</th><th>状态</th><th>创建时间</th><th></th></tr></thead><tbody><tr v-for="item in rows.filter(x=>(x.title+(x.device_id||'')).toLowerCase().includes(query.toLowerCase()))" :key="item.id"><td><strong>{{ item.title }}</strong><small>{{ item.id }}</small></td><td>{{ item.device_id || '未绑定' }}</td><td><span class="pill">{{ item.status }}</span></td><td>{{ new Date(item.created_at).toLocaleString('zh-CN') }}</td><td><RouterLink class="text-link" :to="'/sessions/'+item.id">详情</RouterLink></td></tr></tbody></table><div v-if="!rows.length" class="empty-panel">暂无会话，先去创建一次诊断。</div></div></template></section></template>